'use strict';

angular.module('irtech.netcity.em.events.common')
	.controller('EditEventCtrl', ($scope, $http, $q, $alerts, $uibModal, $dialogs, $uibModalInstance, $longWork, model, Upload, $controller, changeTracker) => {
		const references = require("./../references.coffee");

		const models = require("./../model.coffee");
		const EventMemberViewModel = models.EventMemberViewModel;
		const EventOrgModel = models.EventOrgModel;
		const EventViewModel = models.EventViewModel;

		const editMode = model.event.id > 0;
		$scope.header = `${editMode ? 'Редактирование' : 'Создание'} мероприятия`;

		model.event.eventType = 5 //NetCity.WebServices.WebApi.DTO.Events.EventType.AwardEvents == 5
		model.event.startTime = dateUtils.asUTCDate(model.event.startTime);
		if (editMode) {
			model.event.endTime = dateUtils.asUTCDate(model.event.endTime || model.event.startTime);
		}
		model.event.founder = new EventOrgModel(model.event.founder);
		model.event.organization = new EventOrgModel(model.event.organization);

		const defaultScope = {
			language,
			data: {
				search: {},
				refs: references,
				event: model.event,
				documents: [],
				educYears: model.educYears,
				educYear: _.where(model.educYears, { id: model.event.globalYearId })[0]
			},
			uiState: {
				startTimeOpened: false,
				endTimeOpened: false
			},
			dateOptions: {
				format: dateUtils.getDateFormat(),
				minDate: new Date(),
				maxDate: new Date()
			},
			dateUtil: dateUtils.asUTCDate
		};

		$.extend($scope, defaultScope);

		$scope.globalYearChange = () => {
			const successHandler = (response) => {
				const educYear = response.data;
				$scope.dateOptions.minDate = new Date(educYear.startDate);
				return $scope.dateOptions.maxDate = new Date(educYear.endDate);
			};
			$scope.data.event.globalYearId = $scope.data.educYear.id;
			const options = { params: { educYearId: $scope.data.event.globalYearId } };
			return $http.get("/webapi/em/year", options).then(successHandler);
		};
		$scope.globalYearChange();

		const inCurrentEducYearRange = (date) => {
			if (!date) return true;

			const year = date.getFullYear();
			const month = date.getMonth();
			const day = date.getDate();
			// Отбрасываем время
			date = new Date(year, month, day);
			return (date >= $scope.dateOptions.minDate) && (date <= $scope.dateOptions.maxDate);
		};

		$scope.alerts = {
			isStartBeforeEnd() {
				const { startTime } = $scope.data.event;
				const { endTime } = $scope.data.event;
				return startTime && endTime && ($scope.dateUtil(startTime) > $scope.dateUtil(endTime));
			},
			isInEducYear() {
				const { startTime } = $scope.data.event;
				const { endTime } = $scope.data.event;
				return !(inCurrentEducYearRange(startTime) && inCurrentEducYearRange(endTime));
			}
		};

		const getSaveFileUrl = (eventId) => `/webapi/events/file/${eventId}`;
		const getSaveFilesUrl = (eventId) => `/webapi/events/files/${eventId}`;
		const defaultCatch = response => $alerts.error(response.data.message || response.data.details);

		const postFiles = (eventId, files) => {
			let proxyFiles = files.filter(o => o.isProxy);
			if (proxyFiles.length == 0) return;

			let url = proxyFiles.length > 1
				? getSaveFilesUrl(eventId)
				: getSaveFileUrl(eventId);

			let proxyFilesData = proxyFiles.map(file => file.data);

			return Upload.upload({
				url,
				method: 'POST',
				data: proxyFiles.length == 1
					? proxyFilesData[0]
					: proxyFilesData
			})
				.catch(defaultCatch);
		}

		//создание/редактирование
		$scope.save = () => {
			const formatDate = (currentValue, alternativeValue) => {
				if (currentValue && (currentValue.toString() !== "Invalid Date")) {
					return dateUtils.asUTCDate(currentValue);
				} else {
					return alternativeValue;
				}
			};

			$scope.data.event.startTime = formatDate($scope.data.event.startTime);
			$scope.data.event.endTime = formatDate($scope.data.event.endTime, $scope.data.event.startTime);

			if (!$scope.eventForm.$valid || ($scope.data.event.endTime === "Invalid Date") || $scope.alerts.isStartBeforeEnd() || $scope.alerts.isInEducYear()) {
				$scope.eventForm.$displayErrors = true;
				return;
			}

			$longWork.show();
			const method = editMode ? $http.put : $http.post;
			const request = method("/webapi/events/", $scope.data.event);

			return request
				.then((response) => {
					postFiles(response.data.id, $scope.data.documents);
					$uibModalInstance.close(response.data);
					$alerts.success(language.Generic.Events.kEventSaved);
				})
				.catch(defaultCatch)
				.finally(() => $longWork.close());
		};

		//базовый метод поиска, сохраняющий результат поиска в scope
		$scope.searchItems = (itemType, url, searchData) => {
			if (!searchData || !searchData.name) return;

			$scope.data.search[itemType] = [{ name: 'Поиск...' }];

			return $http.get(url, { params: searchData })
				.then((response) => {
					if (!response.data.length) {
						return $scope.data.search[itemType] = [new EventOrgModel({ other: searchData.name }), { name: 'Совпадений не найдено' }];
					} else {
						return $scope.data.search[itemType] = _.map(response.data, dto => new EventOrgModel(dto));
					}
				}).catch(response => $alerts.error(response.data.message || response.data.details));
		};

		$scope.searchOrg = (searchStr) => {
			if (!searchStr || (searchStr.length < 3)) return;

			$scope.searchItems("orgs", "/webapi/events/orgs/search", { name: searchStr });
		};

		$scope.searchFounder = (searchStr) => {
			if (!searchStr || (searchStr.length < 3)) return;

			$scope.searchItems("founders", "/webapi/events/orgs/search", { name: searchStr });
		};

		//отмена
		$scope.cancel = () => $uibModalInstance.dismiss('cancel');

		if (editMode) {
			$http.get(`/webapi/events/files/${model.event.id}`)
				.then(response => $scope.data.documents = response.data)
				.catch(response => $alerts.error(response.message || response.details));
		}


		let documentIndex = 0;
		//Добавить документ
		$scope.UpdateDocument = (document) => {
			const modalInstance = $uibModal.open({
				templateUrl: "/static/dist/app/em/events/common/fileAttachment/template.html",
				controller: "AddFileAttachmentCtrl",
				size: "md",
				resolve: {
					url() { return getSaveFileUrl(model.event.id); },
					doc() { if (!document) { return {}; } else { return angular.extend({}, document); } },
					lazy: !editMode
				}
			});
			return modalInstance.result.then((result) => {
				if (result.isProxy || result.id === 0)
					result.id = --documentIndex;

				$scope.data.documents = _.without($scope.data.documents, document);
				return $scope.data.documents.push(result);
			});
		};

		const removeProxyDocument = (document) => {
			$scope.data.documents = $scope.data.documents.filter(doc => doc !== document);
		}

		$scope.removeDocument = (document) => {
			const url = `/webapi/events/file/${document.id}/delete`;
			if (document.isProxy) return removeProxyDocument(document);

			return $dialogs.confirm(language.Generic.SchoolInfo.kAreSureDeleteDocument)
				.then(() => $http.delete(url))
				.then(() => {
					$scope.data.documents = _.without($scope.data.documents, document);
					return $alerts.success(language.Generic.SchoolInfo.kDocumentSuccessDeleted);
				}).catch(response => $alerts.error(response.data.message, response.data.details));
		};

		$scope.ready = true;
		$controller("NetCityModalController", { $scope, $dialogs, $uibModalInstance, changeTracker });
	});



