"use strict";

import EventsReferences from "./../references.coffee";
import { EventMemberViewModel, EventOrgModel, EventViewModel } from "./../model.coffee"
import Selectable from "approot/global/selectable";
import * as Rights from "approot/global/references/rights.js";
import { EditUserEventController } from "approot/em/events/common/eventMember/editEventMemberCtrl.js";

export class MemberListCtrl {
	constructor(pageContext, $scope, $http, $q, $alerts, $uibModal, $routeParams, $dialogs, $appLoader) {
		this.language = language;

		pageContext.title = "Информация о мероприятии";
		pageContext.parent = {
			title: "Мероприятия",
			href: "events/list"
		};
		pageContext.back = { history: true };

		if (!$routeParams.eventId) {
			$dialogs.error("Неизвестный идентификатор мероприятия");
			return;
		}

		this.filter = {
			items: {
				eventMemberTitles: [{ id: "All", name: "Все" }].concat(EventsReferences.eventMemberTitles),
				organizations: [{ id: "All", name: "Все" }]
			},
			selected: {
				eventMemberTitle: "All",
				organization: "All"
			}
		};

		this.data = {
			search: {},
			refs: EventsReferences,
			event: { id: $routeParams.eventId },
			members: [],
			viewMembers: []
		};

		this.state = {
			membersReadAccess: _.contains(context.rights, Rights.arEMEventsMembersView) || _.contains(context.rights, Rights.arEMEventsMembersEdit),
			membersWriteAccess: _.contains(context.rights, Rights.arEMEventsMembersEdit),
			ready: false
		};

		this.data.selection = new Selectable();

		this.$http = $http;
		this.$q = $q;
		this.$alerts = $alerts;
		this.$uibModal = $uibModal;
		this.$dialogs = $dialogs;
		this.$appLoader = $appLoader;

		this.load();
	}

	filterMembers() {
		this.data.viewMembers = this.data.members.filter((member) => {
			let show = true;

			if (this.filter.selected.eventMemberTitle !== "All") {
				show = show && (member.title && member.title.id === this.filter.selected.eventMemberTitle);
			}

			if (this.filter.selected.organization !== "All") {
				show = show && (member.organization && member.organization.id === this.filter.selected.organization);
			}

			return show;
		});
	}

	reloadOrganizationsFilter() {
		let organizationsFilterItems =
			_.chain(this.data.members)
				.filter(member => (member.organization))
				.map(member => ({ id: member.organization.id, name: member.organization.name }))
				.uniq(org => org.id)
				.sort(org => org.name)
				.value();

		this.filter.items.organizations = [{ id: "All", name: "Все" }];

		if (organizationsFilterItems) {
			this.filter.items.organizations = this.filter.items.organizations.concat(organizationsFilterItems);
		}

		if (!_.contains(this.filter.items.organizations, this.filter.selected.organization)) {
			this.filter.selected.organization = "All";
		}
	}

	defaultCatch(response) {
		this.$alerts.error(response.data.message || response.data.details);
	}

	//добавить участника
	addMember() {
		let modalInstance = this.$uibModal.open({
			templateUrl: "/static/dist/app/em/events/common/eventMember/template.html",
			controller: EditUserEventController,
			controllerAs: "ctrl",
			resolve: {
				eventMemberId: () => null,
				user: () => null,
				event: () => this.data.event,
				participiationInfo: () => null
			}
		});

		modalInstance.result.then(() => this.load());
	}

	//редактировать участника
	editMember(member) {
		let modalInstance = this.$uibModal.open({
			templateUrl: "/static/dist/app/em/events/common/eventMember/template.html",
			controller: EditUserEventController,
			controllerAs: "ctrl",
			resolve: {
				eventMemberId: () => member.id,
				user: () => member.user,
				event: () => this.data.event,
				participiationInfo: () => angular.copy(member)
			}
		});

		modalInstance.result.then(() => this.load());
	}

	//удалить участника
	removeMember(member) {
		this.$dialogs.confirm("Вы действительно желаете удалить участника?")
			.then(() => this.$http.delete(`/webapi/events/${this.data.event.id}/members/${member.id}`).catch(this.defaultCatch))
			.then(() => {
				this.$alerts.success("Участник успешно удален");
				this.load();
			});
	}

	load() {
		const promises = [];

		const loadEventInfo = this.$http.get(`/webapi/events/${this.data.event.id}`)
			.then((response) => {
				this.data.event = new EventViewModel(response.data);
				this.$http.get(`/webapi/events/files/${this.data.event.id}`)
					.then((response) => {
						this.data.event.documents = response.data;
					});
			})
			.catch(this.defaultCatch);

		const loadEventMembers = () => this.$http.get(`/webapi/events/${this.data.event.id}/members`)
			.then((response) => {
				// сброс выбора
				this.data.selection.dropSelect();

				this.data.members = _.map(response.data, (dto) => new EventMemberViewModel(dto));

				this.reloadOrganizationsFilter();
				this.filterMembers();
			})
			.catch(this.defaultCatch);

		promises.push(loadEventInfo);
		if (this.state.membersReadAccess) {
			promises.push(loadEventMembers());
		}

		this.$q.all(promises).then(() => {
			this.$appLoader.hide();
			this.state.ready = true;
		});
	}
}


